_SUFFIX = {"JR","SR","II","III","IV","V","VI","DECD","ETAL","ETUX","ETVIR"}
_PERSON_TOKENS = _FIRST_NAMES | _SUFFIX
_MAX_PERSON = max(map(len, _PERSON_TOKENS))
_BUSINESS_WORDS = set("""LLC LLP LP LTD INC CORP CORPORATION COMPANY CO TRUST ESTATE ASSOCIATION FOUNDATION PARTNERS PARTNERSHIP VENTURE JOINT INVESTMENTS INVESTMENT PROPERTIES PROPERTY DEVELOPMENT DEVELOPMENTS HOLDINGS HOLDING REALTY RANCH RANCHES FARM FARMS LAND CATTLE BANK CHURCH ISD SCHOOL CEMETERY MINISTRIES HOME HOMES BUILDER BUILDERS CUSTOM BUYERS MANAGEMENT GROUP CAPITAL RESOURCES RESOURCE SERVICES SERVICE CONSTRUCTION ENERGY OIL GAS WATER DISTRICT CITY COUNTY MUNICIPAL ENTERPRISE ENTERPRISES ELECTRIC ELECTRICITY TELEPHONE TELECOM COMMUNITY CENTER CLUB SUNSET OAKS CINCINNATI PRESSURE NO CIRCLE THE OF AND AT ON ACRES REVOCABLE IRREVOCABLE LIVING FAMILY LIMITED GENERAL HOMEOWNERS""".split())
_MAX_BUSINESS = max(map(len, _BUSINESS_WORDS))
_COMPOUND_SUFFIXES = [
    ("IRREVOCABLETRUST", ["IRREVOCABLE", "TRUST"]),
    ("REVOCABLETRUST", ["REVOCABLE", "TRUST"]),
    ("LIVINGTRUST", ["LIVING", "TRUST"]),
    ("FAMILYTRUST", ["FAMILY", "TRUST"]),
    ("TESTAMENTARYTRUST", ["TESTAMENTARY", "TRUST"]),
    ("JOINTVENTURE", ["JOINT", "VENTURE"]),
    ("LIMITEDPARTNERSHIP", ["LIMITED", "PARTNERSHIP"]),
    ("GENERALPARTNERSHIP", ["GENERAL", "PARTNERSHIP"]),
    ("HOMEOWNERSASSOCIATION", ["HOMEOWNERS", "ASSOCIATION"]),
]
_STRONG_ENTITY_MARKERS = (
    "LLC", "LLP", "LTD", "INC", "CORP", "TRUST", "ESTATE", "PARTNER",
    "VENTURE", "ASSOCIATION", "FOUNDATION", "CEMETERY", "RANCH", "CATTLE",
    "HOMES", "HOME", "INVEST", "BANK", "CHURCH", "ISD", "COMPANY"
)


def _owner_compact(value):
    return re.sub(r"[^A-Z0-9]", "", str(value).upper())


def _longest_token_at(text, pos, vocab, max_len):
    for end in range(min(len(text), pos + max_len), pos, -1):
        token = text[pos:end]
        if token in vocab:
            return token
    return None


def _has_known_token_ahead(text, start, vocab, max_len):
    for pos in range(start, len(text)):
        if _longest_token_at(text, pos, vocab, max_len):
            return True
    return False


def _tokenize_known_with_unknown(text, vocab, max_len):
    """Tokenize while keeping unrecognized text in whole chunks.

    A recognized name prefix is not split from a 2-5 character unknown tail when
    there is no later known token.  This avoids bad repairs such as
    CHRISTAL -> CHRIS TAL or ERVIN -> ER VIN.  A one-letter tail is kept as an
    initial, e.g. ROBERTW -> ROBERT W.
    """
    tokens = []
    known = []
    pos = 0
    while pos < len(text):
        token = _longest_token_at(text, pos, vocab, max_len)
        if token:
            end = pos + len(token)
            tail_len = len(text) - end
            if 2 <= tail_len <= 5 and not _has_known_token_ahead(text, end, vocab, max_len):
                tokens.append(text[pos:])
                known.append(False)
                break
            tokens.append(token)
            known.append(True)
            pos = end
            continue

        end = pos + 1
        while end < len(text) and not _longest_token_at(text, end, vocab, max_len):
            end += 1
        tokens.append(text[pos:end])
        known.append(False)
        pos = end
    return tokens, known


def _split_person_compact(text):
    text = _owner_compact(text)
    candidates = []
    if len(text) < 5:
        return None

    # Given-name tokens shorter than 3 letters are too ambiguous to establish a
    # surname boundary. Single-letter initials are still preserved as unknown
    # chunks between recognized names.
    boundary_first_names = {name for name in _FIRST_NAMES if len(name) >= 3}

    for boundary in range(2, min(18, len(text) - 1) + 1):
        surname = text[:boundary]
        remainder = text[boundary:]
        tokens, known_flags = _tokenize_known_with_unknown(
            remainder, _PERSON_TOKENS, _MAX_PERSON
        )
        name_known = [token in _FIRST_NAMES for token in tokens]
        if not any(name_known):
            continue

        first_known = bool(tokens and tokens[0] in boundary_first_names)
        if tokens and tokens[0] in _FIRST_NAMES and not first_known:
            continue
        if not first_known:
            if not tokens or len(tokens[0]) > 8 or not any(name_known[1:]):
                continue

        known_chars = sum(len(token) for token in tokens if token in _FIRST_NAMES)
        unknown_tokens = [token for token, known in zip(tokens, known_flags) if not known]
        unknown_chars = sum(len(token) for token in unknown_tokens)
        long_unknowns = sum(len(token) > 1 for token in unknown_tokens)
        suffix_count = sum(token in _SUFFIX for token in tokens)

        slen = len(surname)
        if 4 <= slen <= 10:
            length_bonus = 7
        elif 3 <= slen <= 12:
            length_bonus = 3
        elif slen <= 2:
            length_bonus = -10
        else:
            length_bonus = -3 * (slen - 12)

        surname_bonus = 10 if surname in _LAST_NAMES else 0
        first_bonus = 10 if first_known else 0
        score = (
            known_chars * 2
            + sum(name_known) * 7
            + suffix_count * 4
            + length_bonus
            + surname_bonus
            + first_bonus
            - unknown_chars * 0.85
            - len(unknown_tokens) * 2.5
            - long_unknowns * 2
        )
        candidates.append(
            {
                "score": score,
                "tokens": [surname] + tokens,
                "surname": surname,
                "surname_known": surname in _LAST_NAMES,
                "name_known_count": int(sum(name_known)),
                "unknown_tokens": unknown_tokens,
                "long_unknowns": long_unknowns,
                "first_known": first_known,
            }
        )

    if not candidates:
        return None
    candidates.sort(key=lambda item: item["score"], reverse=True)
    best = candidates[0]
    second_score = candidates[1]["score"] if len(candidates) > 1 else float("-inf")
    best["margin"] = best["score"] - second_score
    return best


def _peel_compound_suffix(text):
    remainder = text
    suffix=[]
    changed=True
    while changed:
        changed=False
        for compact, tokens in sorted(_COMPOUND_SUFFIXES, key=lambda item: len(item[0]), reverse=True):
            if remainder.endswith(compact) and len(remainder) > len(compact):
                suffix = tokens + suffix
                remainder = remainder[:-len(compact)]
                changed=True
                break
    return remainder, suffix


def _split_entity_compact(text):
    text = _owner_compact(text)
    remainder, suffix = _peel_compound_suffix(text)
    peelable = {
        "LLC","LLP","LP","LTD","INC","CORP","CORPORATION","COMPANY","CO",
        "TRUST","ESTATE","ASSOCIATION","FOUNDATION","PARTNERS","PARTNERSHIP",
        "VENTURE","INVESTMENTS","INVESTMENT","PROPERTIES","PROPERTY","DEVELOPMENT",
        "HOLDINGS","REALTY","RANCH","FARM","LAND","CATTLE","BANK","CHURCH","ISD",
        "CEMETERY","MINISTRIES","HOMES","HOME","BUILDER","BUILDERS","DEPT"
    }
    ending = []
    for _ in range(6):
        found = None
        for token in sorted(peelable, key=len, reverse=True):
            if remainder.endswith(token) and len(remainder) > len(token):
                found = token
                break
        if not found:
            break
        ending.insert(0, found)
        remainder = remainder[:-len(found)]
    suffix = ending + suffix

    if suffix and any(token in {"TRUST", "ESTATE"} for token in suffix):
        person = _split_person_compact(remainder)
        if person and _person_repair_is_safe(person, 0.0):
            return person["score"] + 15, person["tokens"] + suffix

    prefix_tokens, prefix_known = _tokenize_known_with_unknown(
        remainder, _BUSINESS_WORDS, _MAX_BUSINESS
    )
    if not suffix and sum(prefix_known) < 2:
        return None
    score = (
        20
        + sum(len(t) for t, known in zip(prefix_tokens, prefix_known) if known)
        - sum(len(t) for t, known in zip(prefix_tokens, prefix_known) if not known) * 0.25
    )
    return score, prefix_tokens + suffix


def _person_repair_is_safe(person, min_confidence):
    if not person:
        return False
    # Reject highly ambiguous surname boundaries unless the surname itself is a
    # known surname or the parse contains multiple recognized given names.
    if person["margin"] < 4 and not person["surname_known"] and person["name_known_count"] < 2:
        return False
    # More than one long unknown chunk is too speculative for production data.
    if person["long_unknowns"] > 1:
        return False
    return True


def repair_owner_name_scalar(value, person_min_confidence=0.82, entity_min_confidence=0.78):
    raw = "" if value is None else str(value).replace("\u00a0", " ").strip()
    if not raw or raw.casefold() in {"nan", "none", "null", "<na>"}:
        return raw, "missing", 0.0, False
    if re.search(r"\s", raw):
        cleaned = re.sub(r"\s+", " ", raw).strip()
        return cleaned, "source_spaced", 1.0, cleaned != raw

    compact = _owner_compact(raw)
    if not compact:
        return raw, "compressed_unresolved", 0.0, False

    # Entity detection is deliberately suffix/prefix based. Checking whether a
    # marker occurs anywhere caused false positives such as MARTIN... containing
    # the letters INC across a name boundary.
    entity_suffixes = {
        "LLC","LLP","LP","LTD","INC","CORP","CORPORATION","COMPANY","CO",
        "TRUST","ESTATE","ASSOCIATION","FOUNDATION","PARTNERS","PARTNERSHIP",
        "VENTURE","PROPERTIES","PROPERTY","HOLDINGS","REALTY","RANCH","FARM",
        "CATTLE","BANK","CHURCH","ISD","CEMETERY","MINISTRIES","HOMES","HOME",
        "BUILDER","BUILDERS","DEPT"
    }
    entity_prefixes = ("CHURCH", "CEMETERY", "CITYOF", "COUNTYOF", "SCHOOL", "ISD")
    is_entity = (
        any(compact.endswith(token) for token in entity_suffixes)
        or any(compact.endswith(compound) for compound, _ in _COMPOUND_SUFFIXES)
        or compact.startswith(entity_prefixes)
    )

    if is_entity:
        entity = _split_entity_compact(compact)
        if entity:
            score, tokens = entity
            confidence = max(0.70, min(0.99, 0.70 + score / 150.0))
            candidate = " ".join(tokens)
            # Reject outputs that consist of several suspicious 1-2 character
            # fragments; those are a sign the dictionary is over-segmenting.
            tiny_fragments = sum(len(tok) <= 2 and tok not in {"CO", "LP"} for tok in tokens)
            if (
                confidence >= entity_min_confidence
                and candidate != raw
                and tiny_fragments <= 1
            ):
                return candidate, "entity_tokens", round(confidence, 4), True

    person = _split_person_compact(compact)
    if person:
        score = person["score"]
        confidence = max(0.65, min(0.99, 0.60 + score / 130.0))
        candidate = " ".join(person["tokens"])
        if (
            confidence >= person_min_confidence
            and candidate != raw
            and _person_repair_is_safe(person, person_min_confidence)
        ):
            return candidate, "person_surname_first", round(confidence, 4), True
        return raw, "compressed_low_confidence", round(confidence, 4), False

    return raw, "compressed_unresolved", 0.0, False
